import React, { useState } from 'react';
import { Approval, ApprovalType, ApprovalPriority } from '../../../models/Approval';
import { Badge } from '../../common/Badge';
import { Button } from '../../common/Button';
import { formatDistanceToNow } from 'date-fns';
import { vi } from 'date-fns/locale';
import styles from './ApprovalCard.module.css';

interface ApprovalCardProps {
  approval: Approval;
  onApprove: (id: string) => void;
  onReject: (id: string) => void;
  onRequestChanges?: (id: string) => void;
  onViewDetails: (id: string) => void;
  compact?: boolean;
}

export const ApprovalCard: React.FC<ApprovalCardProps> = ({
  approval,
  onApprove,
  onReject,
  onRequestChanges,
  onViewDetails,
  compact = false,
}) => {
  const [expanded, setExpanded] = useState(false);

  const getTypeBadge = (type: ApprovalType) => {
    switch (type) {
      case ApprovalType.TaskClosure:
        return { label: 'Đóng công việc', variant: 'warning' as const };
      case ApprovalType.TaskCreation:
        return { label: 'Tạo công việc', variant: 'primary' as const };
      case ApprovalType.TaskReassignment:
        return { label: 'Chỉ định lại', variant: 'info' as const };
      case ApprovalType.SupportRequest:
        return { label: 'Yêu cầu hỗ trợ', variant: 'info' as const };
      case ApprovalType.ResourceRequest:
        return { label: 'Yêu cầu tài nguyên', variant: 'secondary' as const };
      default:
        return { label: 'Khác', variant: 'secondary' as const };
    }
  };

  const getPriorityBadge = (priority: ApprovalPriority) => {
    switch (priority) {
      case ApprovalPriority.Critical:
        return { label: 'Khẩn cấp', variant: 'danger' as const };
      case ApprovalPriority.High:
        return { label: 'Cao', variant: 'warning' as const };
      case ApprovalPriority.Medium:
        return { label: 'Trung bình', variant: 'info' as const };
      case ApprovalPriority.Low:
        return { label: 'Thấp', variant: 'success' as const };
    }
  };

  const typeBadge = getTypeBadge(approval.type);
  const priorityBadge = getPriorityBadge(approval.priority);

  const timeAgo = approval.requestedAt
    ? formatDistanceToNow(new Date(approval.requestedAt), {
        addSuffix: true,
        locale: vi,
      })
    : 'Unknown time';

  if (compact) {
    return (
      <div className={styles.compactCard}>
        <div className={styles.compactInfo}>
          <div className={styles.compactTitle}>{approval.title}</div>
          <div className={styles.compactMeta}>
            <Badge variant={priorityBadge.variant} size="sm">
              {priorityBadge.label}
            </Badge>
            <span className={styles.compactType}>{typeBadge.label}</span>
            <span className={styles.compactTime}>• {timeAgo}</span>
          </div>
        </div>
        <div className={styles.compactActions}>
          <Button variant="success" size="sm" onClick={() => onApprove(approval.id)}>
            <i className="fas fa-check"></i>
          </Button>
          <Button variant="danger" size="sm" onClick={() => onReject(approval.id)}>
            <i className="fas fa-times"></i>
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div
      className={`${styles.card} ${approval.priority === ApprovalPriority.Critical ? styles.critical : ''} ${expanded ? styles.expanded : ''}`}
      onClick={() => setExpanded((v) => !v)}
    >
      <div className={styles.header}>
        <div className={styles.badges}>
          <Badge variant={typeBadge.variant}>{typeBadge.label}</Badge>
          <Badge variant={priorityBadge.variant}>{priorityBadge.label}</Badge>
          <span className={styles.time}>
            <i className="fas fa-clock"></i>
            {timeAgo}
          </span>
          {approval.isEscalated && (
            <Badge variant="danger">
              <i className="fas fa-exclamation-triangle"></i> Quá hạn
            </Badge>
          )}
        </div>
      </div>

      <div className={styles.content}>
        <h3 className={styles.title}>{approval.title}</h3>
        <p className={styles.description}>{approval.description}</p>

        {/* Requester Info */}
        <div className={styles.requester}>
          <div className={styles.avatar}>
            {approval.requesterAvatar ? (
              <img src={approval.requesterAvatar} alt={approval.requesterName} />
            ) : (
              <span>
                {approval.requesterName
                  .split(' ')
                  .map((n) => n[0])
                  .join('')
                  .toUpperCase()}
              </span>
            )}
          </div>
          <div className={styles.requesterInfo}>
            <div className={styles.requesterName}>{approval.requesterName}</div>
            <div className={styles.requesterRole}>{approval.requesterRole}</div>
          </div>
        </div>

        {/* Task Details */}
        {approval.taskDetails && (
          <div className={styles.taskDetails}>
            <div className={styles.detailsGrid}>
              <div className={styles.detailItem}>
                <div className={styles.detailLabel}>Thời gian ước tính</div>
                <div className={styles.detailValue}>{approval.taskDetails.estimatedHours} giờ</div>
              </div>
              {approval.taskDetails.actualHours && (
                <div className={styles.detailItem}>
                  <div className={styles.detailLabel}>Thời gian thực tế</div>
                  <div className={`${styles.detailValue} ${styles.success}`}>
                    {approval.taskDetails.actualHours} giờ
                  </div>
                </div>
              )}
              <div className={styles.detailItem}>
                <div className={styles.detailLabel}>Tiến độ</div>
                <div className={`${styles.detailValue} ${styles.success}`}>
                  {approval.taskDetails.progress}%
                </div>
              </div>
              <div className={styles.detailItem}>
                <div className={styles.detailLabel}>Trạng thái SLA</div>
                <div
                  className={`${styles.detailValue} ${
                    approval.taskDetails.slaStatus === 'on_time' ? styles.success : styles.warning
                  }`}
                >
                  {approval.taskDetails.slaStatus === 'on_time' ? 'On Time' : 'At Risk'}
                </div>
              </div>
            </div>

            {approval.taskDetails.completionNote && (
              <div className={styles.completionNote}>
                <div className={styles.noteHeader}>
                  <i className="fas fa-comment"></i>
                  Ghi chú hoàn thành:
                </div>
                <p>{approval.taskDetails.completionNote}</p>
              </div>
            )}
          </div>
        )}

        {/* Reason */}
        {approval.reason && (
          <div className={styles.reason}>
            <div className={styles.reasonHeader}>
              <i className="fas fa-exclamation-triangle"></i>
              Lý do yêu cầu phê duyệt:
            </div>
            <p>{approval.reason}</p>
          </div>
        )}

        {/* Impact Info */}
        {(approval.impactedDepartments || approval.impactedUsersCount) && (
          <div className={styles.impact}>
            {approval.impactedDepartments && (
              <div>
                <strong>Phòng ban ảnh hưởng:</strong> {approval.impactedDepartments.join(', ')}
              </div>
            )}
            {approval.impactedUsersCount && (
              <div>
                <strong>Số người dùng ảnh hưởng:</strong> {approval.impactedUsersCount}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Action bar — slides in below card content on click */}
      {expanded && (
        <div className={styles.cardActions} onClick={(e) => e.stopPropagation()}>
        {/* TaskClosure: Approve/Reject only */}
        {approval.type === ApprovalType.TaskClosure && (
          <>
            <Button variant="success" onClick={() => onApprove(approval.id)}>
              <i className="fas fa-check"></i>
              Chấp nhận đóng task
            </Button>
            <Button variant="danger" onClick={() => onReject(approval.id)}>
              <i className="fas fa-times"></i>
              Từ chối
            </Button>
          </>
        )}

        {/* TaskCreation: Approve/Reject/Request Changes */}
        {approval.type === ApprovalType.TaskCreation && (
          <>
            <Button variant="success" onClick={() => onApprove(approval.id)}>
              <i className="fas fa-check"></i>
              Chấp nhận tạo task
            </Button>
            <Button variant="danger" onClick={() => onReject(approval.id)}>
              <i className="fas fa-times"></i>
              Từ chối
            </Button>
            {onRequestChanges && (
              <Button variant="secondary" onClick={() => onRequestChanges(approval.id)}>
                <i className="fas fa-comment"></i>
                Yêu cầu sửa đổi
              </Button>
            )}
          </>
        )}

        {/* TaskReassignment: Approve/Reject/Assign Different */}
        {approval.type === ApprovalType.TaskReassignment && (
          <>
            <Button variant="success" onClick={() => onApprove(approval.id)}>
              <i className="fas fa-check"></i>
              Chấp nhận chuyển giao
            </Button>
            <Button variant="danger" onClick={() => onReject(approval.id)}>
              <i className="fas fa-times"></i>
              Từ chối
            </Button>
            <Button variant="secondary" onClick={() => onViewDetails(approval.id)}>
              <i className="fas fa-user-plus"></i>
              Gán cho người khác
            </Button>
          </>
        )}

        {/* SupportRequest: Approve/Reject */}
        {approval.type === ApprovalType.SupportRequest && (
          <>
            <Button variant="success" onClick={() => onApprove(approval.id)}>
              <i className="fas fa-check"></i>
              Chấp nhận thêm người hỗ trợ
            </Button>
            <Button variant="danger" onClick={() => onReject(approval.id)}>
              <i className="fas fa-times"></i>
              Từ chối
            </Button>
          </>
        )}

        {/* Other types: Default actions */}
        {approval.type !== ApprovalType.TaskClosure &&
          approval.type !== ApprovalType.TaskCreation &&
          approval.type !== ApprovalType.TaskReassignment &&
          approval.type !== ApprovalType.SupportRequest && (
            <>
              <Button variant="success" onClick={() => onApprove(approval.id)}>
                <i className="fas fa-check"></i>
                Chấp nhận
              </Button>
              <Button variant="danger" onClick={() => onReject(approval.id)}>
                <i className="fas fa-times"></i>
                Từ chối
              </Button>
            </>
          )}

        {/* View Details button - always available */}
        <Button variant="secondary" onClick={() => onViewDetails(approval.id)}>
          <i className="fas fa-eye"></i>
          Xem chi tiết task
        </Button>
        </div>
      )}
    </div>
  );
};
