___CSS_LOADER_EXPORT___.push([module.id, `.alert-action-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.alert-action-form__info {
  padding: 1rem;
  background: #f9fafb;
  border-radius: 0.5rem;
  border: 1px solid #e5e7eb;
}

.alert-action-form__info-row {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.alert-action-form__info-row:last-child {
  margin-bottom: 0;
}

.alert-action-form__label {
  font-size: 0.875rem;
  font-weight: 600;
  color: #6b7280;
  min-width: 120px;
}

.alert-action-form__value {
  font-size: 0.875rem;
  color: #111827;
  flex: 1;
}

.alert-action-form__field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.alert-action-form__field-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: #374151;
}

.alert-action-form__field-label.required::after {
  content: ' *';
  color: #dc2626;
}

.alert-action-form__input,
.alert-action-form__select {
  padding: 0.625rem 0.75rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  color: #111827;
  transition: all 0.2s;
}

.alert-action-form__input:focus,
.alert-action-form__select:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.alert-action-form__textarea {
  padding: 0.625rem 0.75rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  color: #111827;
  font-family: inherit;
  resize: vertical;
  transition: all 0.2s;
}

.alert-action-form__textarea:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.alert-action-form__hint {
  font-size: 0.75rem;
  color: #6b7280;
  font-style: italic;
}

.alert-action-form__loading {
  padding: 1rem;
  text-align: center;
  color: #6b7280;
  font-size: 0.875rem;
  font-style: italic;
}

.alert-action-form__empty {
  padding: 1rem;
  text-align: center;
  color: #9ca3af;
  font-size: 0.875rem;
  background: #f9fafb;
  border: 1px dashed #d1d5db;
  border-radius: 0.375rem;
}

.alert-action-form__actions {
  display: flex;
  gap: 0.75rem;
  justify-content: flex-end;
  padding-top: 1rem;
  border-top: 1px solid #e5e7eb;
}

/* Responsive */
@media (max-width: 640px) {
  .alert-action-form__actions {
    flex-direction: column-reverse;
  }

  .alert-action-form__actions button {
    width: 100%;
  }
}
