/**
 * Static sidebar + path guards for `yarn start:std` only.
 * Production shell: menu from @linm/nav + Auth DB (permissions cache).
 */

import type { NavSection } from '@linm-soft/common-components';
import type { AppId } from '../components/layout/AppSwitcher';
import { appPath, resolveAppPath, stripAppPrefix } from '../config/appRoutes';
import { UserRole } from '../models/User';

export function getActiveApp(pathname: string): AppId {
  const path = stripAppPrefix(pathname);
  if (path.startsWith('/medical-incidents')) return 'medical-incidents';
  if (path.startsWith('/fall-location-warnings')) return 'medical-incidents';
  return 'task-management';
}

