/**
 * useMarkConversationRead
 *
 * Centralized hook to mark a conversation as read.
 *
 * Behaviour:
 *  - Marks read immediately on mount (user explicitly opened this view — no visibility guard)
 *  - Re-marks read whenever the user returns to the tab (`visibilitychange` → visible)
 *    or the window regains focus (`focus` event)
 *  - Returns a `markReadIfActive()` helper for SignalR handlers that should only
 *    mark read while the user is actively looking (visibility + focus guard applied there)
 *
 * Usage:
 *   const { markReadIfActive } = useMarkConversationRead('ticket', ticketId);
 *   // markReadIfActive() called in NewMessage SignalR handler
 */

import { useCallback, useEffect } from 'react';
import { useAppDispatch } from '../store/hooks';
import { markConversationReadLocal } from '../store/slices/messagesInboxSlice';
import { conversationEndpoint } from '../services/message/conversationEndpoint';

export function useMarkConversationRead(
  entityType: 'ticket' | 'task' | 'incident',
  entityId: string | undefined,
) {
  const dispatch = useAppDispatch();

  /** Mark read unconditionally (call when user has clearly opened the view). */
  const markRead = useCallback(() => {
    if (!entityId) return;
    dispatch(markConversationReadLocal(entityId));
    conversationEndpoint.markConversationRead(entityType, entityId).catch(() => {});
  }, [dispatch, entityType, entityId]);

  /** Mark read only when the tab is visible AND focused (for SignalR event handlers). */
  const markReadIfActive = useCallback(() => {
    if (!entityId) return;
    if (document.visibilityState === 'visible' && document.hasFocus()) {
      markRead();
    }
  }, [markRead, entityId]);

  // Mark read on mount + re-mark when user returns to the tab/window
  useEffect(() => {
    if (!entityId) return;

    // Immediate on mount — user explicitly opened this view
    markRead();

    const onVisible = () => {
      if (document.visibilityState === 'visible') markRead();
    };
    const onFocus = () => markRead();

    document.addEventListener('visibilitychange', onVisible);
    window.addEventListener('focus', onFocus);
    return () => {
      document.removeEventListener('visibilitychange', onVisible);
      window.removeEventListener('focus', onFocus);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entityType, entityId]); // markRead is stable when entityType/entityId don't change

  return { markRead, markReadIfActive };
}
