/**
 * Custom hook for managing task progress updates
 */

import { useEffect, useState } from 'react';
import { useAppDispatch } from '../../../store/hooks';
import { fetchTaskById } from '../../../store/slices/tasksSlice';
import { Task } from '../../../models/Task';
import { taskService } from '../../../services/task';

interface UseProgressUpdateReturn {
  progress: number;
  setProgress: (value: number) => void;
  handleUpdateProgress: (note?: string) => Promise<void>;
  handleSubmitForReview: () => Promise<void>;
  isUpdating: boolean;
}

/**
 * Hook to manage task progress tracking
 * @param task - Current task object
 * @returns Progress state and update handlers
 */
export const useProgressUpdate = (task: Task | null): UseProgressUpdateReturn => {
  const dispatch = useAppDispatch();
  const [progress, setProgress] = useState(0);
  const [isUpdating, setIsUpdating] = useState(false);

  // Sync local progress state with task progress
  useEffect(() => {
    if (task) {
      setProgress(task.progress);
    }
  }, [task]);

  /**
   * Update task progress via dedicated PATCH /tasks/{id}/progress endpoint
   */
  const handleUpdateProgress = async (note?: string) => {
    if (!task) return;

    setIsUpdating(true);
    try {
      await taskService.updateProgress(task.id, progress, note);
      // Refresh the task to get the updated state
      dispatch(fetchTaskById(task.id));
    } catch (error) {
      console.error('Failed to update progress:', error);
    } finally {
      setIsUpdating(false);
    }
  };

  /**
   * Submit task for review via dedicated PATCH /tasks/{id}/submit endpoint
   */
  const handleSubmitForReview = async () => {
    if (!task) return;

    setIsUpdating(true);
    try {
      await taskService.submitForReview(task.id);
      // Refresh the task to get the updated state
      dispatch(fetchTaskById(task.id));
    } catch (error) {
      console.error('Failed to submit for review:', error);
    } finally {
      setIsUpdating(false);
    }
  };

  return {
    progress,
    setProgress,
    handleUpdateProgress,
    handleSubmitForReview,
    isUpdating,
  };
};
