/**
 * Custom hook for managing task subtasks (checklist operations).
 *
 * All operations call the real BFF subtask endpoints:
 *   GET    /tasks/{id}/subtasks
 *   POST   /tasks/{id}/subtasks
 *   PATCH  /tasks/{id}/subtasks/{subtaskId}
 *   DELETE /tasks/{id}/subtasks/{subtaskId}
 */

import { useState, useEffect, useCallback } from 'react';
import { Subtask } from '../../../models/Task';
import { SubtaskState } from '../types';
import { taskEndpoint } from '../../../services/task/endpoint';

interface UseSubtaskManagerProps {
  taskId: string;
  subtasks: Subtask[];
  initialAutoProgress?: boolean;
  onProgressChange?: (progress: number) => void; // called when auto-progress mode calculates a new value
}

interface UseSubtaskManagerReturn {
  // State
  localSubtasks: Subtask[];
  editingSubtasks: Map<string, SubtaskState>;
  newSubtaskTitle: string;
  setNewSubtaskTitle: (title: string) => void;
  isProcessing: boolean;

  // Auto-progress state
  autoProgressEnabled: boolean;
  showAutoProgressModal: boolean;
  handleAutoProgressToggle: (enabled: boolean) => void;
  handleDismissAutoProgressModal: (enable: boolean) => void;

  // Handlers
  handleToggleSubtask: (subtaskId: string) => Promise<void>;
  handleAddSubtask: () => Promise<void>;
  handleDeleteSubtask: (id: string) => Promise<void>;
  handleStartEditSubtask: (id: string, title: string) => void;
  handleCancelEditSubtask: (id: string) => void;
  handleSaveEditSubtask: (id: string) => Promise<void>;
  handleEditTitleChange: (id: string, title: string) => void;
}

const AUTO_PROGRESS_KEY = (taskId: string) => `task_auto_progress_${taskId}`;
const PROMPT_SHOWN_KEY  = (taskId: string) => `task_checklist_prompt_${taskId}`;

export const useSubtaskManager = ({
  taskId,
  subtasks,
  initialAutoProgress,
  onProgressChange,
}: UseSubtaskManagerProps): UseSubtaskManagerReturn => {
  const [localSubtasks, setLocalSubtasks] = useState<Subtask[]>(subtasks);
  const [editingSubtasks, setEditingSubtasks] = useState<Map<string, SubtaskState>>(new Map());
  const [newSubtaskTitle, setNewSubtaskTitle] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [loaded, setLoaded] = useState(false);

  // Auto-progress state — persisted in localStorage per task
  const [autoProgressEnabled, setAutoProgressEnabled] = useState<boolean>(() => {
    if (initialAutoProgress !== undefined) return initialAutoProgress;
    try { return localStorage.getItem(AUTO_PROGRESS_KEY(taskId)) === 'true'; } catch { return false; }
  });
  // Modal shown when user adds the very first subtask and has never been prompted
  const [showAutoProgressModal, setShowAutoProgressModal] = useState(false);

  // Seed from initial prop (from task detail response), then load fresh from BFF
  useEffect(() => {
    if (subtasks && subtasks.length > 0 && !loaded) {
      setLocalSubtasks(subtasks);
    }
  }, [subtasks, loaded]);

  // Load subtasks from BFF on mount
  useEffect(() => {
    if (!taskId || loaded) return;
    let cancelled = false;
    const timer = setTimeout(() => {
      if (cancelled) return;
      (async () => {
        try {
          const bffSubtasks = await taskEndpoint.getSubtasks(taskId);
          if (!cancelled) {
            setLocalSubtasks(
              bffSubtasks.map((s) => ({ id: s.id, title: s.title, completed: s.completed }))
            );
            setLoaded(true);
          }
        } catch {
          // Fallback: keep initial prop subtasks (from task detail response)
          if (!cancelled) setLoaded(true);
        }
      })();
    }, 0);
    return () => { cancelled = true; clearTimeout(timer); };
  }, [taskId, loaded]);

  /** Calculate progress from current subtask list */
  const calcProgress = useCallback((list: Subtask[]): number => {
    if (!list.length) return 0;
    return Math.round((list.filter((s) => s.completed).length / list.length) * 100);
  }, []);

  /** Toggle auto-progress mode */
  const handleAutoProgressToggle = useCallback((enabled: boolean) => {
    setAutoProgressEnabled(enabled);
    try { localStorage.setItem(AUTO_PROGRESS_KEY(taskId), String(enabled)); } catch { /* ignore */ }
    if (enabled) {
      // Immediately sync progress with current checklist state
      onProgressChange?.(calcProgress(localSubtasks));
    }
  }, [taskId, localSubtasks, calcProgress, onProgressChange]);

  /** Respond to the first-use confirmation modal */
  const handleDismissAutoProgressModal = useCallback((enable: boolean) => {
    setShowAutoProgressModal(false);
    try { localStorage.setItem(PROMPT_SHOWN_KEY(taskId), 'true'); } catch { /* ignore */ }
    if (enable) handleAutoProgressToggle(true);
  }, [taskId, handleAutoProgressToggle]);

  /** Toggle subtask completion via PATCH */
  const handleToggleSubtask = useCallback(async (subtaskId: string) => {
    if (!taskId) return;
    const current = localSubtasks.find((st) => st.id === subtaskId);
    if (!current) return;
    const newCompleted = !current.completed;

    // Optimistic update
    const updatedList = localSubtasks.map((st) =>
      st.id === subtaskId ? { ...st, completed: newCompleted } : st
    );
    setLocalSubtasks(updatedList);

    // Auto-progress sync
    if (autoProgressEnabled) {
      onProgressChange?.(calcProgress(updatedList));
    }

    setIsProcessing(true);
    try {
      await taskEndpoint.updateSubtask(taskId, subtaskId, { completed: newCompleted });
    } catch {
      // Rollback on error
      const rolledBack = localSubtasks.map((st) =>
        st.id === subtaskId ? { ...st, completed: !newCompleted } : st
      );
      setLocalSubtasks(rolledBack);
      if (autoProgressEnabled) onProgressChange?.(calcProgress(rolledBack));
    } finally {
      setIsProcessing(false);
    }
  }, [taskId, localSubtasks, autoProgressEnabled, calcProgress, onProgressChange]);

  /** Add new subtask via POST */
  const handleAddSubtask = useCallback(async () => {
    if (!taskId || !newSubtaskTitle.trim()) return;

    // Show first-use modal if never prompted and list was empty
    const isFirstSubtask = localSubtasks.length === 0;
    const promptShown = (() => {
      try { return localStorage.getItem(PROMPT_SHOWN_KEY(taskId)) === 'true'; } catch { return false; }
    })();
    if (isFirstSubtask && !promptShown) {
      setShowAutoProgressModal(true);
    }

    setIsProcessing(true);
    try {
      const created = await taskEndpoint.addSubtask(
        taskId,
        newSubtaskTitle.trim(),
        localSubtasks.length
      );
      const newList = [
        ...localSubtasks,
        { id: created.id, title: created.title, completed: created.completed },
      ];
      setLocalSubtasks(newList);
      setNewSubtaskTitle('');
      // Auto-progress update (new subtask is not completed, so progress drops)
      if (autoProgressEnabled) onProgressChange?.(calcProgress(newList));
    } finally {
      setIsProcessing(false);
    }
  }, [taskId, newSubtaskTitle, localSubtasks, autoProgressEnabled, calcProgress, onProgressChange]);

  /** Delete subtask via DELETE */
  const handleDeleteSubtask = useCallback(async (subtaskId: string) => {
    if (!taskId) return;
    // Optimistic remove
    const snapshot = localSubtasks;
    const newList = localSubtasks.filter((st) => st.id !== subtaskId);
    setLocalSubtasks(newList);
    if (autoProgressEnabled) onProgressChange?.(calcProgress(newList));

    setIsProcessing(true);
    try {
      await taskEndpoint.deleteSubtask(taskId, subtaskId);
    } catch {
      setLocalSubtasks(snapshot);
      if (autoProgressEnabled) onProgressChange?.(calcProgress(snapshot));
    } finally {
      setIsProcessing(false);
    }
  }, [taskId, localSubtasks, autoProgressEnabled, calcProgress, onProgressChange]);

  const handleStartEditSubtask = useCallback((subtaskId: string, currentTitle: string) => {
    setEditingSubtasks((prev) => {
      const newMap = new Map(prev);
      newMap.set(subtaskId, { isEditing: true, title: currentTitle });
      return newMap;
    });
  }, []);

  const handleCancelEditSubtask = useCallback((subtaskId: string) => {
    setEditingSubtasks((prev) => {
      const newMap = new Map(prev);
      newMap.delete(subtaskId);
      return newMap;
    });
  }, []);

  /** Save edited title via PATCH */
  const handleSaveEditSubtask = useCallback(async (subtaskId: string) => {
    if (!taskId) return;
    const editState = editingSubtasks.get(subtaskId);
    if (!editState || !editState.title.trim()) return;

    const newTitle = editState.title.trim();
    // Optimistic update
    setLocalSubtasks((prev) =>
      prev.map((st) => (st.id === subtaskId ? { ...st, title: newTitle } : st))
    );
    handleCancelEditSubtask(subtaskId);

    setIsProcessing(true);
    try {
      await taskEndpoint.updateSubtask(taskId, subtaskId, { title: newTitle });
    } catch {
      // On error revert to original title (we lost the original, so refresh from BFF)
      try {
        const fresh = await taskEndpoint.getSubtasks(taskId);
        setLocalSubtasks(fresh.map((s) => ({ id: s.id, title: s.title, completed: s.completed })));
      } catch { /* ignore */ }
    } finally {
      setIsProcessing(false);
    }
  }, [taskId, editingSubtasks, handleCancelEditSubtask]);

  const handleEditTitleChange = useCallback((subtaskId: string, newTitle: string) => {
    setEditingSubtasks((prev) => {
      const editState = prev.get(subtaskId);
      if (!editState) return prev;
      const newMap = new Map(prev);
      newMap.set(subtaskId, { ...editState, title: newTitle });
      return newMap;
    });
  }, []);

  return {
    localSubtasks,
    editingSubtasks,
    newSubtaskTitle,
    setNewSubtaskTitle,
    isProcessing,
    autoProgressEnabled,
    showAutoProgressModal,
    handleAutoProgressToggle,
    handleDismissAutoProgressModal,
    handleToggleSubtask,
    handleAddSubtask,
    handleDeleteSubtask,
    handleStartEditSubtask,
    handleCancelEditSubtask,
    handleSaveEditSubtask,
    handleEditTitleChange,
  };
};

