/**
 * ActivityCard Component
 * Individual activity item in the timeline
 */

import React, { useState } from 'react';
import { HistoryItem, getPriorityBadgeVariant, getPriorityText, formatTimeSpent } from '../../../models/History';
import styles from './ActivityCard.module.css';

interface ActivityCardProps {
  item: HistoryItem;
}

export const ActivityCard: React.FC<ActivityCardProps> = ({ item }) => {
  const [expanded, setExpanded] = useState(false);

  const completedTime = item.completedAt
    ? new Date(item.completedAt).toLocaleTimeString('vi-VN', {
        hour: '2-digit',
        minute: '2-digit',
      })
    : '';

  const priorityVariant = getPriorityBadgeVariant(item.priority);
  const priorityText = getPriorityText(item.priority);

  return (
    <div className={styles.activityCard}>
      <div className={styles.cardHeader}>
        <div className={styles.badges}>
          <span className={`${styles.badge} ${styles.badgeSuccess}`}>
            Hoàn thành
          </span>
          <span className={`${styles.badge} ${styles[priorityVariant]}`}>
            {priorityText}
          </span>
          {completedTime && (
            <span className={styles.time}>{completedTime}</span>
          )}
        </div>
      </div>

      <div className={styles.cardBody}>
        <h4 className={styles.title}>
          {item.entityCode} - {item.entityTitle}
        </h4>
        <p className={styles.description}>{item.actionDescription}</p>

        <div className={styles.metadata}>
          <span className={styles.metaItem}>
            <i className="fas fa-clock" style={{ color: 'var(--info-color)' }}></i>
            {formatTimeSpent(item.timeSpent)}
            {item.estimatedTime && ` (ước tính: ${formatTimeSpent(item.estimatedTime)})`}
          </span>

          {item.rating && (
            <span className={styles.metaItem}>
              <i className="fas fa-star" style={{ color: '#fbbf24' }}></i>
              Đánh giá: {item.rating.toFixed(1)}
            </span>
          )}

          {item.slaStatus === 'breached' && item.slaBreachMinutes && (
            <span className={styles.metaItem} style={{ color: 'var(--danger-color)' }}>
              <i className="fas fa-exclamation-triangle"></i>
              Vi phạm SLA {item.slaBreachMinutes} phút
            </span>
          )}
        </div>

        {/* Expandable Details */}
        {item.metadata && (
          <>
            {expanded && (
              <div className={styles.details}>
                {item.metadata.department && (
                  <div className={styles.detailRow}>
                    <span className={styles.detailLabel}>Phòng ban:</span>
                    <span className={styles.detailValue}>{item.metadata.department}</span>
                  </div>
                )}
                {item.metadata.category && (
                  <div className={styles.detailRow}>
                    <span className={styles.detailLabel}>Danh mục:</span>
                    <span className={styles.detailValue}>{item.metadata.category}</span>
                  </div>
                )}
                <div className={styles.detailRow}>
                  <span className={styles.detailLabel}>Loại:</span>
                  <span className={styles.detailValue}>
                    {item.type === 'ticket' ? 'Phiếu yêu cầu' : 'Công việc'}
                  </span>
                </div>
              </div>
            )}

            <button
              className={styles.expandButton}
              onClick={() => setExpanded(!expanded)}
            >
              <i className={`fas fa-chevron-${expanded ? 'up' : 'down'}`}></i>
              {expanded ? 'Thu gọn' : 'Xem chi tiết'}
            </button>
          </>
        )}
      </div>
    </div>
  );
};
