import React from 'react';
import { MemoryRouter } from 'react-router-dom';
import { Provider } from 'react-redux';
import { store } from './store/store';
import App from './App';
import { MemoryRouterSync } from './router/MemoryRouterSync';
import { ensureAppPrefixedPath } from './config/appRoutes';

const initialPath =
  typeof window !== 'undefined'
    ? ensureAppPrefixedPath(window.location.pathname) + window.location.search || '/'
    : '/';

const Root: React.FC = () => (
  <Provider store={store}>
    <MemoryRouter initialEntries={[initialPath]} initialIndex={0}>
      <MemoryRouterSync />
      <App />
    </MemoryRouter>
  </Provider>
);

export default Root;
