/**
 * HistoryStatsCards Component
 * Summary statistics cards for work history
 */

import React from 'react';
import { HistoryStats } from '../../../models/History';
import { StatsCard, StatsCardsGrid } from '../../common';

interface HistoryStatsCardsProps {
  stats: HistoryStats;
}

export const HistoryStatsCards: React.FC<HistoryStatsCardsProps> = ({ stats }) => {
  return (
    <StatsCardsGrid>
      <StatsCard
        label="Tổng đã hoàn thành"
        value={stats.totalCompleted}
        icon="fas fa-check-circle"
        variant="total"
      />
      <StatsCard
        label="Tháng này"
        value={stats.completedThisMonth}
        icon="fas fa-calendar-check"
        variant="success"
      />
      <StatsCard
        label="Tuần này"
        value={stats.completedThisWeek}
        icon="fas fa-calendar-week"
        variant="info"
      />
      <StatsCard
        label="Tổng thời gian"
        value={`${stats.totalTimeSpent}h`}
        icon="fas fa-clock"
        variant="warning"
      />
      <StatsCard
        label="Đánh giá TB"
        value={stats.averageRating.toFixed(1)}
        icon="fas fa-star"
        variant="primary"
      />
      <StatsCard
        label="Đúng hẹn"
        value={`${stats.onTimePercentage}%`}
        icon="fas fa-bullseye"
        variant="success"
      />
      <StatsCard
        label="Vi phạm SLA"
        value={stats.slaBreaches}
        icon="fas fa-exclamation-triangle"
        variant="danger"
      />
    </StatsCardsGrid>
  );
};
