/** UI path segment — distinguishes @linm/m-inc routes from other MFEs on the Linm shell. */
export const APP_UI_PREFIX = 'm-inc';

const SHELL_PUBLIC_PATHS = new Set([
  '/login',
  '/logout',
  '/unauthorized',
  '/session-expired',
  '/oidc-callback',
  '/oidc-silent-renew',
]);

/** First URL segment for routes owned by this MFE (Auth menu paths often omit `/m-inc`). */
const DOMAIN_FIRST_SEGMENTS = new Set([
  'tickets',
  'tasks',
  'task-pool',
  'department-tasks',
  'approvals',
  'sla-alerts',
  'reports',
  'statistics',
  'history',
  'admin',
  'medical-incidents',
  'fall-location-warnings',
  'dev',
]);

/** Absolute in-app path: `/m-inc/...` (API URLs are unchanged). */
export function appPath(path = ''): string {
  const trimmed = path.replace(/^\/+/, '');
  if (!trimmed) return `/${APP_UI_PREFIX}`;
  if (trimmed === APP_UI_PREFIX || trimmed.startsWith(`${APP_UI_PREFIX}/`)) {
    return `/${trimmed}`;
  }
  return `/${APP_UI_PREFIX}/${trimmed}`;
}

/** Menu / Auth paths may omit the prefix — normalize for navigation. */
export function resolveAppPath(path: string): string {
  if (!path || path === '/') return appPath('tickets');
  return appPath(path);
}

/** Compare permission menu paths (often without prefix) to the current URL. */
export function stripAppPrefix(pathname: string): string {
  const base = pathname.replace(/\/+$/, '') || '/';
  const prefix = `/${APP_UI_PREFIX}`;
  if (base === prefix) return '/';
  if (base.startsWith(`${prefix}/`)) return base.slice(prefix.length) || '/';
  return base;
}

function normalizePathname(pathname: string): string {
  if (!pathname || pathname === '/') return '/';
  return pathname.endsWith('/') ? pathname.slice(0, -1) : pathname;
}

/** True when pathname is a domain screen (with or without `/m-inc`). */
export function isDomainBrowserPath(pathname: string): boolean {
  const path = stripAppPrefix(normalizePathname(pathname));
  if (path === '/') return false;
  const first = path.split('/').filter(Boolean)[0];
  return !!first && DOMAIN_FIRST_SEGMENTS.has(first);
}

/**
 * Canonical browser URL for this MFE.
 * Auth/sidebar may use `/tickets`; shell route + MemoryRouter expect `/m-inc/tickets`.
 */
export function ensureAppPrefixedPath(pathname: string): string {
  const base = normalizePathname(pathname);
  const prefix = `/${APP_UI_PREFIX}`;
  if (base === prefix || base.startsWith(`${prefix}/`)) return base;
  if (SHELL_PUBLIC_PATHS.has(base)) return base;
  if (!isDomainBrowserPath(base)) return base;
  return appPath(base.replace(/^\//, ''));
}
